package layouts

import (
	"math"
	"strings"

	"gonetsurf/dom"
	"gonetsurf/parsers/css/parser"
	"gonetsurf/parsers/css/tokenizer"
	cssvalues "gonetsurf/parsers/css/values"
	"gonetsurf/styles"
)

// BoxKind identifies the kind of box generated by an element or text node.
type BoxKind uint8

const (
	// BlockBox is a block-level box.
	BlockBox BoxKind = iota
	// InlineBox is an inline-level box.
	InlineBox
	// TextBox is a text run.
	TextBox
	// AnonymousBlockBox wraps inline runs in a mixed block container.
	AnonymousBlockBox
)

// Length is a computed length. Auto and percentage values are retained until
// layout resolves them against a containing block.
type Length struct {
	Value   float64
	Percent bool
	Auto    bool
}

// Resolve resolves the length against a base.
func (length Length) Resolve(base float64) float64 {
	if length.Auto {
		return 0
	}
	if length.Percent {
		return base * length.Value / 100
	}
	return length.Value
}

// Edges is a set of four lengths.
type Edges struct {
	Top    Length
	Right  Length
	Bottom Length
	Left   Length
}

// Horizontal returns the resolved left plus right edge.
func (edges Edges) Horizontal(base float64) float64 {
	return edges.Left.Resolve(base) + edges.Right.Resolve(base)
}

// Vertical returns the resolved top plus bottom edge.
func (edges Edges) Vertical(base float64) float64 {
	return edges.Top.Resolve(base) + edges.Bottom.Resolve(base)
}

// Box is a node in the CSS box tree.
type Box struct {
	Node       *dom.Node
	Pseudo     string
	Style      *styles.Style
	Kind       BoxKind
	Text       string
	VisualText string
	Parent     *Box

	Children []*Box

	Margin  Edges
	Padding Edges
	Border  Edges

	// Geometry. X/Y and Width/Height are the border box; ContentX/ContentY
	// and ContentWidth/ContentHeight are the content box.
	X, Y          float64
	Width, Height float64
	ContentX      float64
	ContentY      float64
	ContentWidth  float64
	ContentHeight float64

	FontSize     float64
	LineHeight   float64
	Ascent       float64
	TextRotation float64
	ZIndex       int

	IntrinsicMinWidth      float64
	IntrinsicMaxWidth      float64
	ScrollWidth            float64
	ScrollHeight           float64
	ScrollLeft             float64
	ScrollTop              float64
	ClipX                  bool
	ClipY                  bool
	ScrollX                bool
	ScrollY                bool
	HasHorizontalScrollbar bool
	HasVerticalScrollbar   bool
	StaticX                float64
	StaticY                float64
	HasStaticPosition      bool
	LaidOut                bool
	ContainingX            float64
	ContainingY            float64
	ContainingWidth        float64
	ContainingHeight       float64
	intrinsicsComputed     bool
}

// IsBlockLevel reports whether the box participates in block layout.
func (box *Box) IsBlockLevel() bool {
	return box.Kind == BlockBox || box.Kind == AnonymousBlockBox
}

// BuildDocument builds the box tree for a document using the styles computed
// by engine.
func BuildDocument(document *dom.Document, engine *styles.Engine) *Box {
	if document == nil || engine == nil {
		return nil
	}
	computed := engine.ComputeDocumentTree(document)
	pseudo := computePseudoStyles(&document.Node, engine, computed)
	return buildRoot(&document.Node, computed, pseudo)
}

// BuildTree builds the box tree for an element subtree and computes styles
// with engine.
func BuildTree(root *dom.Node, engine *styles.Engine) *Box {
	if root == nil || engine == nil {
		return nil
	}
	return Build(root, engine.ComputeTree(root))
}

// Build builds the box tree rooted at root using the supplied computed styles.
// If root is a Document, its document element is used.
func Build(root *dom.Node, computed map[*dom.Node]*styles.Style) *Box {
	return buildRoot(root, computed, nil)
}

func buildRoot(root *dom.Node, computed map[*dom.Node]*styles.Style, pseudo map[*dom.Node]map[string]*styles.Style) *Box {
	if root == nil {
		return nil
	}
	if root.Type == dom.DocumentNode {
		var documentElement *dom.Node
		for _, child := range root.Children() {
			if child.Type == dom.ElementNode {
				documentElement = child
				break
			}
		}
		if documentElement == nil {
			return nil
		}
		root = documentElement
	}
	if root.Type != dom.ElementNode {
		return nil
	}
	style := computed[root]
	if style == nil {
		return nil
	}
	boxes := buildNode(root, computed, pseudo, style)
	if len(boxes) == 0 {
		return nil
	}
	return boxes[0]
}

func buildNode(node *dom.Node, computed map[*dom.Node]*styles.Style, pseudo map[*dom.Node]map[string]*styles.Style, inherited *styles.Style) []*Box {
	switch node.Type {
	case dom.TextNode:
		if inherited == nil || strings.TrimSpace(node.Data) == "" {
			return nil
		}
		box := &Box{
			Node:  node,
			Style: inherited,
			Kind:  TextBox,
			Text:  node.Data,
		}
		box.FontSize, box.LineHeight = fontMetrics(inherited)
		return []*Box{box}
	case dom.ElementNode:
	default:
		return nil
	}
	style := computed[node]
	if style == nil {
		return nil
	}
	display := normalizeDisplay(style.GetString("display"))
	if display == "" {
		display = "inline"
	}
	if display == "none" {
		return nil
	}
	children := []*Box{}
	if before := buildPseudoBox(node, "before", pseudo); before != nil {
		children = append(children, before)
	}
	for _, child := range node.Children() {
		children = append(children, buildNode(child, computed, pseudo, style)...)
	}
	if after := buildPseudoBox(node, "after", pseudo); after != nil {
		children = append(children, after)
	}
	if display == "contents" {
		return children
	}
	kind := BlockBox
	if isInlineDisplay(display) {
		kind = InlineBox
	}
	box := &Box{
		Node:     node,
		Style:    style,
		Kind:     kind,
		Margin:   styleEdges(style, "margin"),
		Padding:  styleEdges(style, "padding"),
		Border:   borderEdges(style),
		Children: children,
	}
	box.FontSize, box.LineHeight = fontMetrics(style)
	box.Ascent = MetricsForStyle(style).Ascent
	box.TextRotation = textRotation(style.GetString("writing-mode"))
	box.ZIndex = parseZIndex(style.GetString("z-index"))
	box.ClipX = clipsOverflow(style.GetString("overflow-x"))
	box.ClipY = clipsOverflow(style.GetString("overflow-y"))
	box.ScrollX = scrollsOverflow(style.GetString("overflow-x"))
	box.ScrollY = scrollsOverflow(style.GetString("overflow-y"))
	for _, child := range children {
		child.Parent = box
	}
	if box.Kind == BlockBox {
		box.Children = wrapAnonymous(box.Children, style)
	}
	return []*Box{box}
}

func computePseudoStyles(root *dom.Node, engine *styles.Engine, computed map[*dom.Node]*styles.Style) map[*dom.Node]map[string]*styles.Style {
	if root == nil || engine == nil || !engine.HasGeneratedContent() {
		return nil
	}
	result := map[*dom.Node]map[string]*styles.Style{}
	root.Descendants(func(node *dom.Node) bool {
		if node.Type != dom.ElementNode {
			return true
		}
		parentStyle := computed[node]
		if parentStyle == nil {
			return true
		}
		for _, pseudo := range []string{"before", "after"} {
			if !engine.HasPseudoElement(pseudo) {
				continue
			}
			style := engine.ComputePseudo(node, parentStyle, pseudo)
			if style == nil {
				continue
			}
			if _, ok := generatedContent(node, style); !ok {
				continue
			}
			if result[node] == nil {
				result[node] = map[string]*styles.Style{}
			}
			result[node][pseudo] = style
		}
		return true
	})
	if len(result) == 0 {
		return nil
	}
	return result
}

func buildPseudoBox(node *dom.Node, pseudo string, pseudoStyles map[*dom.Node]map[string]*styles.Style) *Box {
	stylesByPseudo := pseudoStyles[node]
	if stylesByPseudo == nil {
		return nil
	}
	style := stylesByPseudo[pseudo]
	if style == nil {
		return nil
	}
	content, ok := generatedContent(node, style)
	if !ok {
		return nil
	}
	display := normalizeDisplay(style.GetString("display"))
	if display == "" {
		display = "inline"
	}
	if display == "none" {
		return nil
	}
	kind := BlockBox
	if isInlineDisplay(display) {
		kind = InlineBox
	}
	box := &Box{
		Pseudo:  pseudo,
		Style:   style,
		Kind:    kind,
		Margin:  styleEdges(style, "margin"),
		Padding: styleEdges(style, "padding"),
		Border:  borderEdges(style),
	}
	box.FontSize, box.LineHeight = fontMetrics(style)
	box.Ascent = MetricsForStyle(style).Ascent
	box.TextRotation = textRotation(style.GetString("writing-mode"))
	box.ZIndex = parseZIndex(style.GetString("z-index"))
	box.ClipX = clipsOverflow(style.GetString("overflow-x"))
	box.ClipY = clipsOverflow(style.GetString("overflow-y"))
	box.ScrollX = scrollsOverflow(style.GetString("overflow-x"))
	box.ScrollY = scrollsOverflow(style.GetString("overflow-y"))
	if content != "" {
		textBox := &Box{
			Style:  style,
			Kind:   TextBox,
			Text:   content,
			Parent: box,
		}
		textBox.FontSize, textBox.LineHeight = fontMetrics(style)
		textBox.Ascent = MetricsForStyle(style).Ascent
		box.Children = []*Box{textBox}
	}
	if box.Kind == BlockBox {
		box.Children = wrapAnonymous(box.Children, style)
	}
	return box
}

func generatedContent(node *dom.Node, style *styles.Style) (string, bool) {
	if style == nil {
		return "", false
	}
	text := strings.TrimSpace(style.GetString("content"))
	if text == "" || strings.EqualFold(text, "normal") || strings.EqualFold(text, "none") {
		return "", false
	}
	var builder strings.Builder
	found := false
	for _, value := range parser.ParseComponentValueList(text) {
		if parser.IsWhitespace(value) {
			continue
		}
		if token, ok := parser.AsToken(value); ok {
			switch token.Type {
			case tokenizer.TokenString:
				builder.WriteString(token.Value)
				found = true
			case tokenizer.TokenIdent:
				switch strings.ToLower(token.Value) {
				case "open-quote":
					builder.WriteRune('"')
					found = true
				case "close-quote":
					builder.WriteRune('"')
					found = true
				}
			}
			continue
		}
		if function, ok := value.(*parser.Function); ok && strings.EqualFold(function.Name, "attr") {
			name := strings.TrimSpace(parser.SerializeValues(function.Value))
			if comma := strings.IndexByte(name, ','); comma >= 0 {
				name = strings.TrimSpace(name[:comma])
			}
			name = strings.Trim(name, "\"'")
			if name != "" {
				found = true
				if value, exists := node.GetAttribute(name); exists {
					builder.WriteString(value)
				}
			}
		}
	}
	return builder.String(), found
}

func isInlineDisplay(display string) bool {
	switch normalizeDisplay(display) {
	case "inline", "inline-block", "inline-flex", "inline-grid", "inline-table",
		"ruby", "ruby-base", "ruby-text", "ruby-base-container", "ruby-text-container":
		return true
	default:
		return false
	}
}

// normalizeDisplay converts the CSS Display 3 multi-keyword forms into the
// legacy single-keyword values used by the layout engine.
func normalizeDisplay(display string) string {
	tokens := strings.Fields(strings.ToLower(strings.TrimSpace(display)))
	if len(tokens) == 0 {
		return ""
	}
	if len(tokens) == 1 {
		return tokens[0]
	}
	outsideInline := false
	inside := "flow"
	flowRoot := false
	for _, token := range tokens {
		switch token {
		case "inline":
			outsideInline = true
		case "block":
		case "flow-root":
			flowRoot = true
		case "flex", "grid", "table", "ruby":
			inside = token
		case "inline-flex", "inline-grid", "inline-table", "inline-block":
			outsideInline = true
			switch token {
			case "inline-flex":
				inside = "flex"
			case "inline-grid":
				inside = "grid"
			case "inline-table":
				inside = "table"
			case "inline-block":
				return "inline-block"
			}
		}
	}
	if outsideInline {
		switch inside {
		case "flex":
			return "inline-flex"
		case "grid":
			return "inline-grid"
		case "table":
			return "inline-table"
		case "flow":
			if flowRoot {
				return "inline-block"
			}
			return "inline"
		}
	}
	switch inside {
	case "flex", "grid", "table", "ruby":
		return inside
	}
	if flowRoot {
		return "flow-root"
	}
	return "block"
}

func wrapAnonymous(children []*Box, style *styles.Style) []*Box {
	hasBlock := false
	for _, child := range children {
		if child.IsBlockLevel() {
			hasBlock = true
			break
		}
	}
	if !hasBlock {
		return children
	}
	result := []*Box{}
	inlineRun := []*Box{}
	flush := func() {
		if len(inlineRun) == 0 {
			return
		}
		anonymous := &Box{
			Style:    style,
			Kind:     AnonymousBlockBox,
			Children: inlineRun,
		}
		anonymous.FontSize, anonymous.LineHeight = fontMetrics(style)
		for _, child := range inlineRun {
			child.Parent = anonymous
		}
		result = append(result, anonymous)
		inlineRun = nil
	}
	for _, child := range children {
		if child.IsBlockLevel() {
			flush()
			result = append(result, child)
			continue
		}
		inlineRun = append(inlineRun, child)
	}
	flush()
	return result
}

func styleEdges(style *styles.Style, prefix string) Edges {
	return Edges{
		Top:    parseLength(style.GetString(prefix + "-top")),
		Right:  parseLength(style.GetString(prefix + "-right")),
		Bottom: parseLength(style.GetString(prefix + "-bottom")),
		Left:   parseLength(style.GetString(prefix + "-left")),
	}
}

func borderEdges(style *styles.Style) Edges {
	return Edges{
		Top:    borderLength(style, "top"),
		Right:  borderLength(style, "right"),
		Bottom: borderLength(style, "bottom"),
		Left:   borderLength(style, "left"),
	}
}

func borderLength(style *styles.Style, side string) Length {
	borderStyle := strings.ToLower(strings.TrimSpace(style.GetString("border-" + side + "-style")))
	if borderStyle == "" || borderStyle == "none" || borderStyle == "hidden" {
		return Length{}
	}
	return parseLength(style.GetString("border-" + side + "-width"))
}

func parseLength(text string) Length {
	text = strings.TrimSpace(text)
	if text == "" {
		return Length{}
	}
	if strings.EqualFold(text, "auto") {
		return Length{Auto: true}
	}
	values := parser.ParseComponentValueList(text)
	if len(values) != 1 {
		return Length{}
	}
	numeric, ok := cssvalues.ParseNumeric(values[0])
	if !ok {
		return Length{}
	}
	if numeric.Unit == "%" {
		return Length{Value: numeric.Number * 100, Percent: true}
	}
	if numeric.Kind == cssvalues.Length {
		return Length{Value: numeric.Number}
	}
	if numeric.Kind == cssvalues.Other && numeric.Unit == "" {
		return Length{Value: numeric.Number}
	}
	return Length{}
}

func textRotation(writingMode string) float64 {
	switch strings.ToLower(strings.TrimSpace(writingMode)) {
	case "vertical-rl", "sideways-rl":
		return 90
	case "vertical-lr", "sideways-lr":
		return -90
	default:
		return 0
	}
}

func scrollsOverflow(value string) bool {
	switch strings.ToLower(strings.TrimSpace(value)) {
	case "scroll", "auto":
		return true
	default:
		return false
	}
}

func clipsOverflow(value string) bool {
	switch strings.ToLower(strings.TrimSpace(value)) {
	case "hidden", "clip", "scroll", "auto":
		return true
	default:
		return false
	}
}

func parseZIndex(text string) int {
	values := parser.ParseComponentValueList(strings.TrimSpace(text))
	if len(values) != 1 {
		return 0
	}
	token, ok := parser.AsToken(values[0])
	if !ok || token.Type != tokenizer.TokenNumber || token.NumericKind != tokenizer.Integer {
		return 0
	}
	return int(token.Number)
}

func fontMetrics(style *styles.Style) (float64, float64) {
	fontSize := 16.0
	values := parser.ParseComponentValueList(style.GetString("font-size"))
	if len(values) == 1 {
		if numeric, ok := cssvalues.ParseNumeric(values[0]); ok && numeric.Kind == cssvalues.Length {
			fontSize = numeric.Number
		}
	}
	lineHeight := fontSize * 1.2
	text := strings.TrimSpace(style.GetString("line-height"))
	if text != "" && !strings.EqualFold(text, "normal") {
		values := parser.ParseComponentValueList(text)
		if len(values) == 1 {
			if numeric, ok := cssvalues.ParseNumeric(values[0]); ok {
				if numeric.Unit == "%" {
					lineHeight = fontSize * numeric.Number
				} else if numeric.Kind == cssvalues.Length {
					lineHeight = numeric.Number
				} else if numeric.Kind == cssvalues.Other && numeric.Unit == "" {
					lineHeight = fontSize * numeric.Number
				}
			}
		}
	}
	return fontSize, lineHeight
}

// ScrollbarThickness is the reserved scrollbar size used by scrollport
// calculations.
const ScrollbarThickness = 15.0

// ScrollportWidth returns the content width available inside the scrollbars.
func (box *Box) ScrollportWidth() float64 {
	if box.HasVerticalScrollbar {
		return math.Max(0, box.ContentWidth-ScrollbarThickness)
	}
	return box.ContentWidth
}

// ScrollportHeight returns the content height available inside the scrollbars.
func (box *Box) ScrollportHeight() float64 {
	if box.HasHorizontalScrollbar {
		return math.Max(0, box.ContentHeight-ScrollbarThickness)
	}
	return box.ContentHeight
}

// ScrollContainer returns the nearest ancestor scroll container, or nil.
func (box *Box) ScrollContainer() *Box {
	return box.scrollContainer()
}

// StickyOffset returns the visual position of a sticky box for a scroll
// container offset. Non-sticky boxes return their layout position.
func (box *Box) StickyOffset(scrollX, scrollY float64) (float64, float64) {
	if box == nil || box.Style == nil {
		return 0, 0
	}
	position := strings.ToLower(strings.TrimSpace(box.Style.GetString("position")))
	if position != "sticky" {
		return box.X, box.Y
	}
	container := box.scrollContainer()
	if container == nil {
		return box.X, box.Y
	}
	x, y := box.X, box.Y
	viewportX := container.ContentX + scrollX
	viewportY := container.ContentY + scrollY
	left := parseOffset(box.Style.GetString("left"))
	right := parseOffset(box.Style.GetString("right"))
	top := parseOffset(box.Style.GetString("top"))
	bottom := parseOffset(box.Style.GetString("bottom"))
	minX := viewportX
	maxX := viewportX + container.ScrollportWidth() - box.Width
	minY := viewportY
	maxY := viewportY + container.ScrollportHeight() - box.Height
	if !left.Auto {
		minX += left.Resolve(container.ContentWidth)
	} else if !right.Auto {
		maxX -= right.Resolve(container.ContentWidth)
	}
	if !top.Auto {
		minY += top.Resolve(container.ContentHeight)
	} else if !bottom.Auto {
		maxY -= bottom.Resolve(container.ContentHeight)
	}
	if x < minX {
		x = minX
	}
	if x > maxX {
		x = maxX
	}
	if y < minY {
		y = minY
	}
	if y > maxY {
		y = maxY
	}
	if parent := box.Parent; parent != nil {
		if x > parent.ContentX+parent.ContentWidth-box.Width {
			x = parent.ContentX + parent.ContentWidth - box.Width
		}
		if y > parent.ContentY+parent.ContentHeight-box.Height {
			y = parent.ContentY + parent.ContentHeight - box.Height
		}
	}
	return x, y
}

func (box *Box) scrollContainer() *Box {
	for parent := box.Parent; parent != nil; parent = parent.Parent {
		if parent.ClipX || parent.ClipY {
			return parent
		}
	}
	return nil
}

// MaxScrollLeft returns the maximum horizontal scroll offset.
func (box *Box) MaxScrollLeft() float64 {
	return math.Max(0, box.ScrollWidth-box.ScrollportWidth())
}

// MaxScrollTop returns the maximum vertical scroll offset.
func (box *Box) MaxScrollTop() float64 {
	return math.Max(0, box.ScrollHeight-box.ScrollportHeight())
}

// ScrollTo sets the scroll offsets, clamped to the scrollable range.
func (box *Box) ScrollTo(left, top float64) {
	box.ScrollLeft = math.Max(0, math.Min(box.MaxScrollLeft(), left))
	box.ScrollTop = math.Max(0, math.Min(box.MaxScrollTop(), top))
}

// ScrollBy adjusts the scroll offsets by the given deltas.
func (box *Box) ScrollBy(deltaX, deltaY float64) {
	box.ScrollTo(box.ScrollLeft+deltaX, box.ScrollTop+deltaY)
}
